(()=>{const schema=ShotSchema,merge=schema.merge,pack=schema.pack;schema.merge=function(project,raw){const result=merge(project,raw);result.project.audioTimelineState=JSON.parse(JSON.stringify(project.audioTimelineState||{}));if(raw.global_audio?.timeline_version==='1.0')AudioTimeline.validate(result.project);return result;};schema.pack=function(project){const out=pack(project);out.global_audio=JSON.parse(JSON.stringify(AudioTimeline.global(project)));return out;};})();
